export interface FooterProps {
  columns?: FooterColumn[];
  social?: SocialLink[];
}

export default function Footer({
  columns = footerColumns,
  social = socialLinks
}: FooterProps) {
  return (
    <footer className="border-t border-white/5 bg-slate-950">
      <div className="mx-auto grid max-w-[1440px] gap-10 px-6 py-16 lg:grid-cols-[1.3fr_4fr] lg:gap-8">
        <div>
          <FooterLogoMark className="h-auto w-full max-w-[350px]" />
          <p className="mt-4 text-sm uppercase tracking-[0.2em] text-slate-500">{siteConfig.tagline}</p>
          <p className="mt-4 max-w-xs text-sm text-slate-400">
            Expedition travel at its highest standard — delivering journeys that go beyond the ordinary.
          </p>
        </div>
        <div className='grid md:grid-cols-2 lg:grid-cols-4 gap-8'>
          {columns.map((column) => (
            <nav key={column.heading} aria-label={column.heading}>
              <h2 className="text-xs font-semibold uppercase tracking-[0.22em] text-slate-500">{column.heading}</h2>
              <ul className="mt-4 space-y-3">
                {column.links.map((link) => (
                  <li key={`${link.href}-${link.label}`}>
                    <Link href={link.href} className="cursor-hover text-sm text-slate-400 transition-colors duration-300 ease-in-out hover:text-white">
                      {link.label}
                    </Link>
                  </li>
                ))}
              </ul>
            </nav>
          ))}

          <div>
            <h2 className="text-xs font-semibold uppercase tracking-[0.22em] text-slate-500">Get In Touch</h2>
            <ul className="mt-4 space-y-3 text-sm text-slate-400">
              <li className="flex items-center gap-2">
                <Phone size={15} className="text-apex-300" />
                <a href={siteConfig.contactPhoneHref} className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
                  {siteConfig.contactPhone}
                </a>
              </li>
              <li className="flex items-center gap-2">
                <WhatsAppIcon size={15} className="text-apex-300" />
                <WhatsAppLink
                  href={buildWhatsAppLink({ messageText: 'Hi The Apex Voyager India, I want to plan a custom Himalayan journey.' })}
                  target="_blank"
                  rel="noreferrer"
                  className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white"
                >
                  WhatsApp Us
                </WhatsAppLink>
              </li>
              <li className="flex flex-wrap items-center gap-2">
                <Mail size={15} className="text-apex-300" />
                <a
                  href={`mailto:${siteConfig.contactEmail}`}
                  className="cursor-hover min-w-0 flex-1 break-words transition-colors duration-300 ease-in-out hover:text-white text-nowrap"
                >
                  {siteConfig.contactEmail}
                </a>
              </li>
            </ul>
            <div className="mt-5 flex items-center gap-3">
              {social.map(({ label, href, icon: Icon }) => (
                <a
                  key={label}
                  href={href}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={label}
                  className="cursor-hover flex h-9 w-9 items-center justify-center rounded-full border border-white/10 text-slate-300 transition-colors duration-300 ease-in-out hover:border-apex-400/60 hover:text-white"
                >
                  <Icon size={16} />
                </a>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="border-t border-white/5 px-6 py-6 sm:px-10 lg:px-16">
        <div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-3 text-xs text-slate-500 sm:flex-row">
          <p>
            © {new Date().getFullYear()} {siteConfig.name}. All rights reserved.
          </p>
          <div className="flex flex-wrap justify-center gap-x-6 gap-y-2">
            <Link href="/terms" className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
              Terms &amp; Conditions
            </Link>
            <Link href="/privacy" className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
              Privacy
            </Link>
            <Link href="/faqs" className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
              FAQs
            </Link>
            <Link href="/accessibility-policy" className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
              Accessibility
            </Link>
            <Link href="/photo-credits" className="cursor-hover transition-colors duration-300 ease-in-out hover:text-white">
              Photo Credits
            </Link>
          </div>
        </div>
      </div>
    </footer>
  );
}
